# VenueRecord: dataclass + validator
from dataclasses import dataclass, field
from typing import Any

@dataclass
class Venuerecord:
    venue_id: str = None  # ID
    name: str = None  # Name
    city: str = None  # City
    capacity: float = None  # Seats
    kind: str = None  # theatre/arena/club

REQUIRED = ["venue_id", "name", "city", "capacity"]

def validate(rec: dict) -> list:
    errors = []
    for f in REQUIRED:
        if f not in rec or rec[f] is None:
            errors.append(f'missing: {f}')
    return errors

sample = {'venue_id': 'V-RICHARD', 'name': 'Richard Rodgers Theatre', 'city': 'New York', 'capacity': 1319, 'kind': 'theatre'}
print('validation errors:', validate(sample))
print('record ok:', not validate(sample))

# TicketTier: dataclass + validator
from dataclasses import dataclass, field
from typing import Any

@dataclass
class Tickettier:
    tier_id: str = None  # ID
    perf_id: str = None  # FK
    name: str = None  # e.g. Orchestra
    price_usd: float = None  # Price
    qty: float = None  # Seats in tier

REQUIRED = ["tier_id", "perf_id", "name", "price_usd"]

def validate(rec: dict) -> list:
    errors = []
    for f in REQUIRED:
        if f not in rec or rec[f] is None:
            errors.append(f'missing: {f}')
    return errors

sample = {'tier_id': 'TT-01', 'perf_id': 'PF-77120', 'name': 'Orchestra', 'price_usd': 199, 'qty': 400}
print('validation errors:', validate(sample))
print('record ok:', not validate(sample))
